{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Omadacycline absolute oral bioavailability was 34.5% in humans (300 mg oral vs 100 mg IV), directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Apixaban absolute oral bioavailability was 0.49 (49%) after a 10 mg oral dose in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Loperamide absolute oral bioavailability was 0.3% at therapeutic doses in humans, directly arguing against F >= 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct absolute F values above 20% for omadacycline and apixaban, together with multiple additional positive absolute F records, support high bioavailability; high-score loperamide and butorphanol records are contradictory but do not overturn the positive evidence.",
  "evidence_gaps": [
    "Loperamide has conflicting absolute (0.3%) and unspecified (~40%) bioavailability reports.",
    "Omadacycline has an outlier absolute F estimate (0.00663) and a high-fat meal value (0.6%) conflicting with 34.5% fasted values.",
    "Butorphanol has a threshold-adjacent 20% oral-route estimate alongside absolute 5-17%; idarubicin and encainide ranges include values below 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

